import fs from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';

// Scope Bootstrap to application and portalled React-Bootstrap components.
const input = new URL('../node_modules/bootstrap/dist/css/bootstrap.css', import.meta.url);
const output = new URL('../src/styles/bootstrap.scoped.css', import.meta.url);
const root = postcss.parse(await fs.readFile(input, 'utf8'), { from: fileURLToPath(input) });
root.walkRules(rule => {
  if (rule.parent.type === 'atrule' && /keyframes$/i.test(rule.parent.name)) return;
  rule.selectors = rule.selectors.flatMap(selector => {
    if (selector === ':root' || selector === '[data-bs-theme=light]') return '.bs-ui';
    if (selector === 'body') return '.bs-ui';
    // Portalled Modal/Backdrop nodes carry bs-ui on the node itself, outside #root.
    // Include that root form as well as descendants of the application scope.
    return selector.startsWith('.')
      ? [`.bs-ui ${selector}`, `.bs-ui${selector}`]
      : [`.bs-ui ${selector}`];
  });
});
await fs.mkdir(new URL('../src/styles/', import.meta.url), { recursive: true });
await fs.writeFile(output, '/* Generated by scripts/scope-bootstrap.mjs; Bootstrap license retained below. */\n' + root.toString().replace(/\/\*# sourceMappingURL=.*?\*\//g, '').trimEnd() + '\n');
console.log('Generated scoped Bootstrap CSS');
